@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Beam Custom — hand-rolled rainbow border-beam effect.
 *
 * Inspired by beam.jakubantalik.com, this DS replicates the traveling
 * conic-gradient beam around interactive surfaces using pure CSS — no
 * runtime JS, no third-party library. Effect is built from:
 *   1. A masked conic gradient on ::after (the beam stroke)
 *   2. A blurred glow on ::before (the bloom layer)
 *   3. CSS @property + @keyframes to rotate the gradient
 *
 * Theme: deep neutral surface with magenta primary that pairs with the
 * rainbow spectrum. Cards and inputs sit on a near-black plane so the
 * beam reads cleanly without competing with surface color.
 */

:root {
  --background: oklch(0.12 0 0);
  --foreground: oklch(0.97 0.005 280);

  --card: oklch(0.15 0 0);
  --card-foreground: oklch(0.97 0.005 280);

  --popover: oklch(0.17 0 0);
  --popover-foreground: oklch(0.97 0.005 280);

  --primary: oklch(0.66 0.24 340);
  --primary-foreground: oklch(0.99 0 0);

  --secondary: oklch(0.2 0 0);
  --secondary-foreground: oklch(0.92 0 0);

  --muted: oklch(0.18 0 0);
  --muted-foreground: oklch(0.62 0.005 280);

  --accent: oklch(0.22 0.04 320);
  --accent-foreground: oklch(0.97 0.01 320);

  --destructive: oklch(0.64 0.22 25);
  --destructive-foreground: oklch(0.97 0 0);

  --border: oklch(1 0 0 / 0.08);
  --input: oklch(1 0 0 / 0.05);
  --ring: oklch(0.66 0.24 340);
  --radius: 0.875rem;

  --beam-1: rgb(255, 50, 100);
  --beam-2: rgb(40, 140, 255);
  --beam-3: rgb(50, 200, 80);
  --beam-4: rgb(30, 185, 170);
  --beam-5: rgb(100, 70, 255);
  --beam-6: rgb(255, 120, 40);
  --beam-7: rgb(240, 50, 180);
  --beam-8: rgb(180, 40, 240);

  --shadow-s:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-m:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 2px 4px rgba(0, 0, 0, 0.5),
    0 4px 8px rgba(0, 0, 0, 0.25);
  --shadow-l:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 4px 8px rgba(0, 0, 0, 0.6),
    0 8px 16px rgba(0, 0, 0, 0.3);
  --shadow-inset:
    inset 0 1px 2px rgba(0, 0, 0, 0.4),
    inset 0 -1px 0 rgba(255, 255, 255, 0.03);
  --shadow-button:
    inset 0 1px 0 rgba(255, 255, 255, 0.10),
    0 0 0 1px rgba(255, 255, 255, 0.04),
    0 1px 2px rgba(0, 0, 0, 0.5);
  --shadow-button-hover:
    inset 0 1px 0 rgba(255, 255, 255, 0.14),
    0 0 0 1px rgba(255, 255, 255, 0.06),
    0 2px 4px rgba(0, 0, 0, 0.55);
  --shadow-primary:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 0 0 1px rgba(255, 80, 180, 0.25),
    0 1px 3px rgba(0, 0, 0, 0.5),
    0 4px 12px rgba(255, 60, 160, 0.18);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 4px);
  --radius-xl: calc(var(--radius) + 8px);
  --shadow-inset: var(--shadow-inset);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
